import { DateTime } from 'luxon';
import * as rruleNs from 'rrule';

// rrule ships CJS for Node; normalize named vs default interop.
const { RRule } = (rruleNs as unknown as { default?: typeof rruleNs }).default ?? rruleNs;
type RRule = InstanceType<typeof RRule>;

export interface RecurringSource {
  startAt: Date;
  endAt: Date;
  allDay: boolean;
  timezone: string;
  rrule: string | null;
  exdates: Date[];
}

export interface Occurrence {
  start: Date;
  end: Date;
  /** Start of the occurrence as generated by the rule (used to match exceptions/overrides). */
  originalStart: Date;
}

const zoneFor = (src: Pick<RecurringSource, 'allDay' | 'timezone'>) => (src.allDay ? 'UTC' : safeZone(src.timezone));

export function safeZone(tz: string | null | undefined): string {
  if (!tz) return 'UTC';
  return DateTime.now().setZone(tz).isValid ? tz : 'UTC';
}

/** Instant -> "floating" Date whose UTC fields equal the wall-clock time in `zone`. */
function toFloating(instant: Date, zone: string): Date {
  const l = DateTime.fromJSDate(instant, { zone });
  return new Date(Date.UTC(l.year, l.month - 1, l.day, l.hour, l.minute, l.second));
}

/** Floating Date -> real instant, interpreting its UTC fields as wall-clock time in `zone` (DST-aware). */
function fromFloating(floating: Date, zone: string): Date {
  return DateTime.fromObject(
    {
      year: floating.getUTCFullYear(),
      month: floating.getUTCMonth() + 1,
      day: floating.getUTCDate(),
      hour: floating.getUTCHours(),
      minute: floating.getUTCMinutes(),
      second: floating.getUTCSeconds(),
    },
    { zone },
  ).toJSDate();
}

export function stripRrulePrefix(rule: string): string {
  return rule.replace(/^RRULE:/i, '').trim();
}

function buildRule(src: RecurringSource): RRule {
  const zone = zoneFor(src);
  const options = RRule.parseString(stripRrulePrefix(src.rrule!));
  if (options.until) options.until = toFloating(options.until, zone);
  return new RRule({ ...options, dtstart: toFloating(src.startAt, zone), tzid: null });
}

/**
 * Expand a (possibly recurring) event into concrete occurrences overlapping [rangeStart, rangeEnd).
 * Expansion happens in the event's own timezone so recurring local times survive DST changes.
 */
export function expandOccurrences(src: RecurringSource, rangeStart: Date, rangeEnd: Date, maxCount = 2000): Occurrence[] {
  const duration = src.endAt.getTime() - src.startAt.getTime();
  if (!src.rrule) {
    const overlaps = src.startAt < rangeEnd && (src.endAt > rangeStart || (duration === 0 && src.startAt >= rangeStart));
    return overlaps ? [{ start: src.startAt, end: src.endAt, originalStart: src.startAt }] : [];
  }
  const zone = zoneFor(src);
  const rule = buildRule(src);
  const windowStart = toFloating(new Date(rangeStart.getTime() - duration), zone);
  const windowEnd = toFloating(rangeEnd, zone);
  const excluded = new Set(src.exdates.map((d) => d.getTime()));
  const out: Occurrence[] = [];
  for (const f of rule.between(windowStart, windowEnd, true)) {
    const start = fromFloating(f, zone);
    if (excluded.has(start.getTime())) continue;
    const end = src.allDay
      ? fromFloating(new Date(f.getTime() + duration), zone)
      : new Date(start.getTime() + duration);
    if (start >= rangeEnd || end <= rangeStart) {
      if (!(duration === 0 && start >= rangeStart && start < rangeEnd)) continue;
    }
    out.push({ start, end, originalStart: start });
    if (out.length >= maxCount) break;
  }
  return out;
}

/** Returns true if `instant` is a generated occurrence start of the series. */
export function isOccurrenceOf(src: RecurringSource, instant: Date): boolean {
  if (!src.rrule) return src.startAt.getTime() === instant.getTime();
  const hits = expandOccurrences({ ...src, exdates: [] }, new Date(instant.getTime() - 1000), new Date(instant.getTime() + 1000));
  return hits.some((o) => o.start.getTime() === instant.getTime());
}

function formatUtc(d: Date): string {
  return d.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
}

/** End a series just before `occurrenceStart` (used for "this and following" edits). */
export function truncateRule(rule: string, occurrenceStart: Date): string {
  const parts = stripRrulePrefix(rule)
    .split(';')
    .filter((p) => !/^(UNTIL|COUNT)=/i.test(p));
  parts.push(`UNTIL=${formatUtc(new Date(occurrenceStart.getTime() - 1000))}`);
  return parts.join(';');
}

/** Human-readable description for UI badges, e.g. "every week on Monday". */
export function describeRule(rule: string): string {
  try {
    return RRule.fromString(stripRrulePrefix(rule)).toText();
  } catch {
    return 'custom recurrence';
  }
}
